#ifndef COMMON_H
#define COMMON_H

#include "types.h"
#if defined(TARGET_PC)
/* the PC port includes no MIPS assembly: the rodata is in the executable it
 * loads, at its addresses */
#define INCLUDE_ASM(FOLDER, NAME)
#define INCLUDE_RODATA(FOLDER, NAME)
#elif !defined(M2CTX)
#include "include_asm.h" /* generated by splat (make extract) */
#endif

/* file-local variables of the game. The PC port uses them at their
 * PlayStation addresses, which position-independent code (Android) can only
 * reach for global symbols. */
#ifdef TARGET_PC
#define STATIC_DATA
#else
#define STATIC_DATA static
#endif

/* A pointer the game may read through while it is NULL (it then reads the
 * low mirror of the RAM, 0x00000000-0x001FFFFF on the console): the PC port
 * reads the RAM itself (on Android a fault handler does the same for any
 * such read; on Windows and Linux x86 only the places marked so). */
#ifdef TARGET_PC
#define PSX_MIRROR(p) ((u32)(p) < 0x200000u ? (void *)((u32)(p) | 0x80000000u) : (void *)(p))
#else
#define PSX_MIRROR(p) ((void *)(p))
#endif

#endif /* COMMON_H */
